package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.entity.TravelRequest; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.TravelRequestService; import EmployeeManagementSystem.service.RequestScopeService;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/travel") public class TravelRequestController{
 private final TravelRequestService service; private final JwtUtil jwt; private final EmployeeRepository employees; private final RequestScopeService scope;
 public TravelRequestController(TravelRequestService s,JwtUtil j,EmployeeRepository e,RequestScopeService requestScope){service=s;jwt=j;employees=e;scope=requestScope;}
 private String tok(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(tok(a));} private String role(String a){String r=jwt.extractRole(tok(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private void mgmt(String r){if(!Set.of("ADMIN","HR","MANAGER").contains(r))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");}
 @GetMapping("/my") public List<TravelRequest> my(@RequestHeader("Authorization")String a){return service.my(user(a));}
 @GetMapping("/all") public List<TravelRequest> all(@RequestHeader("Authorization")String a){String currentRole=role(a);mgmt(currentRole);return scope.visibleTo(currentRole,user(a),service.all());}
 @PostMapping public TravelRequest create(@RequestHeader("Authorization")String a,@RequestBody TravelRequest x){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(z->z.getFullName()).orElse(u);try{return service.create(x,u,n);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PutMapping("/{id}") public TravelRequest update(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody TravelRequest x){try{return service.update(id,x,user(a));}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/{id}/review") public TravelRequest review(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,Object>b){String currentRole=role(a);mgmt(currentRole);scope.assertCanReviewById(currentRole,user(a),service.all(),id);try{return service.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")),user(a));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @DeleteMapping("/{id}") public Map<String,Object> delete(@PathVariable Long id,@RequestHeader("Authorization")String a){try{service.delete(id,user(a));return Map.of("success",true);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
}
